@push('scripts')<script>$(function(){const element=$('#stock-policies-table'),text=$.fn.dataTable.render.text(),table=element.DataTable($.extend(true,{},window.erpDataTableDefaults,{processing:true,serverSide:true,order:[[1,'asc']],ajax:'{{ route('wms.stock-policies.data') }}',buttons:[window.erpExcelButton(element)],columns:[window.erpRowNumberColumn(),{data:'item_label',name:'item.name',render:text.display},{data:'warehouse_label',name:'warehouse.name',render:text.display},{data:'min_quantity',name:'min_quantity',className:'text-end',render:text.display},{data:'max_quantity',name:'max_quantity',className:'text-end',render:text.display},{data:'reorder_quantity',name:'reorder_quantity',className:'text-end',render:text.display},{data:'status_label',name:'is_active',render:(value,type,row)=>type==='display'?'<span class="badge '+(row.is_active?'app-status-success':'app-status-neutral')+'">'+text.display(value)+'</span>':value},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:(value,type,row)=>{if(type!=='display')return '';let html=row.edit_url?'<a class="btn btn-sm btn-app-soft" href="'+row.edit_url+'" title="แก้ไข" aria-label="แก้ไขนโยบาย"><i class="bx bx-edit" aria-hidden="true"></i></a>':'';if(row.delete_url)html+=' <button type="button" class="btn btn-sm btn-app-danger js-policy-delete" data-url="'+row.delete_url+'" title="ลบ" aria-label="ลบนโยบาย"><i class="bx bx-trash" aria-hidden="true"></i></button>';return html;}}]}));window.erpAjaxDelete({button:'.js-policy-delete',reload:'#stock-policies-table',title:'ลบนโยบาย Min/Max?',text:'การแจ้งเตือนสต็อกสำหรับรายการนี้จะหยุดทำงาน',confirmButtonText:'ลบ',cancelButtonText:'กลับ'});});</script>@endpush
